#!/usr/bin/env python3
"""Evergreen Persian explainers ("P/E چیست؟", "ETF چیست؟" ...) as blog articles in the blog `learn`.

The text is fixed; the worked example in each article is filled from today's data (data/stocks/*.json),
so the numbers stay current. Pushed by sync_guides.py.
Output: pages/explainers.json  {blog, blog_title, articles: [...]}
"""
import json, os

from build_pages import fa, pct, big_fa
from build_guides import CSS, DIS, faq_block, chips, date_fa, TODAY

ROOT = os.environ.get('GITHUB_WORKSPACE', os.getcwd())
OUT = os.path.join(ROOT, 'pages', 'explainers.json')


def stock(t):
    try:
        return json.load(open(os.path.join(ROOT, 'data', 'stocks', t + '.json')))
    except Exception:
        return {}


def n(v, d=1):
    return fa(('%.' + str(d) + 'f') % v) if v is not None else '—'


def ctx():
    a, k, m, v = stock('AAPL'), stock('KO'), stock('MSFT'), stock('NVDA')
    am, ar, as_ = a.get('market') or {}, a.get('ratios') or {}, a.get('summary') or {}
    kr, ks, km = k.get('ratios') or {}, k.get('summary') or {}, k.get('market') or {}
    eps = (am['price'] / ar['pe']) if am.get('price') and ar.get('pe') else None
    gap = (ar['fair_mcap'] / am['mcap'] - 1) if ar.get('fair_mcap') and am.get('mcap') else None
    dy = kr.get('div_yield')
    return dict(
        aapl_price=n(am.get('price'), 2), aapl_pe=n(ar.get('pe')), aapl_eps=n(eps, 2), aapl_mcap=big_fa(am.get('mcap')),
        aapl_fcf=big_fa((a.get('latest') or {}).get('fcf')), aapl_roic=pct(as_.get('roic_avg_5y')),
        aapl_margin=pct(as_.get('net_margin_avg_5y')), aapl_sh=pct(abs(as_.get('sh_cagr_3y') or 0), 1),
        aapl_gap=(pct(abs(gap)) + (' بالاتر' if gap >= 0 else ' پایین‌تر')) if gap is not None else '—',
        aapl_pfcf=n(ar.get('pfcf')), aapl_bb=pct(ar.get('buyback_yield'), 1),
        ko_dy=pct(dy, 1), ko_years=fa(ks.get('div_years') or 0), ko_price=n(km.get('price'), 2),
        ko_1000=n(1000 * dy, 0) if dy else '—',
        msft_pe=n((m.get('ratios') or {}).get('pe')), nvda_pe=n((v.get('ratios') or {}).get('pe')),
        nvda_mcap=big_fa((v.get('market') or {}).get('mcap')), msft_mcap=big_fa((m.get('market') or {}).get('mcap')),
        nvda_margin=pct((v.get('summary') or {}).get('net_margin_avg_1y')),
    )


